WITH recent_employees AS (SELECT *, LOWER(full_name) AS full_name_lower FROM employees WHERE manager_id = 13), level_summary AS (SELECT level, SUM(CASE WHEN level = 'L1' THEN salary ELSE 0 END) AS l1_salary, COUNT(CASE WHEN level = 'L5' THEN 1 END) AS l5_count FROM recent_employees GROUP BY level) SELECT level, l5_count FROM level_summary WHERE l5_count < 5 ORDER BY level, l5_count DESC LIMIT 50;
